-- ============================================================================
-- MASSACHUSETTS SCHOOL DISTRICT - LOAD SYNTHETIC DATA
-- ============================================================================
-- 
-- This script loads synthetic data generated by the Faker-based Python script
-- into the RAW layer tables using SCD Type 2 patterns.
--
-- PREREQUISITES:
-- 1. Run the faker_data_generator.py script to generate CSV files
-- 2. Upload CSV files to a Snowflake stage
-- 3. Execute this script to load into RAW tables
--
-- RUN AS: DATA_ADMIN
-- ============================================================================

USE ROLE DATA_ADMIN;
USE WAREHOUSE LOAD_WH;
USE DATABASE RAW_DEV;

-- ═══════════════════════════════════════════════════════════════════════════
-- PART 1: CREATE STAGING SCHEMA AND FILE FORMAT
-- ═══════════════════════════════════════════════════════════════════════════

CREATE SCHEMA IF NOT EXISTS STAGING;

CREATE OR REPLACE FILE FORMAT STAGING.CSV_FORMAT
    TYPE = CSV
    FIELD_DELIMITER = ','
    SKIP_HEADER = 1
    FIELD_OPTIONALLY_ENCLOSED_BY = '"'
    NULL_IF = ('', 'NULL', 'null')
    EMPTY_FIELD_AS_NULL = TRUE
    ESCAPE_UNENCLOSED_FIELD = NONE
    DATE_FORMAT = 'YYYY-MM-DD'
    TIMESTAMP_FORMAT = 'YYYY-MM-DD HH24:MI:SS';

-- Create stage for data files
CREATE OR REPLACE STAGE STAGING.DATA_STAGE
    FILE_FORMAT = STAGING.CSV_FORMAT
    COMMENT = 'Stage for loading synthetic education data';

-- ═══════════════════════════════════════════════════════════════════════════
-- PART 2: CREATE STAGING TABLES
-- ═══════════════════════════════════════════════════════════════════════════

-- Staging table for districts
CREATE OR REPLACE TABLE STAGING.STG_DISTRICT (
    DISTRICT_ID VARCHAR(20),
    DISTRICT_NAME VARCHAR(100),
    COUNTY VARCHAR(50),
    CITY VARCHAR(50),
    STATE VARCHAR(2),
    SUPERINTENDENT_NAME VARCHAR(100),
    PHONE_MAIN VARCHAR(20),
    WEBSITE VARCHAR(200),
    CURRENT_SCHOOL_YEAR VARCHAR(10)
);

-- Staging table for schools
CREATE OR REPLACE TABLE STAGING.STG_SCHOOL (
    SCHOOL_ID VARCHAR(20),
    SCHOOL_NAME VARCHAR(100),
    SCHOOL_NAME_SHORT VARCHAR(50),
    SCHOOL_TYPE VARCHAR(30),
    GRADE_LEVELS_SERVED VARCHAR(20),
    IS_TITLE_I BOOLEAN,
    IS_MAGNET BOOLEAN,
    IS_CHARTER BOOLEAN,
    DISTRICT_ID VARCHAR(20),
    DISTRICT_NAME VARCHAR(100),
    ADDRESS VARCHAR(200),
    CITY VARCHAR(50),
    STATE VARCHAR(2),
    ZIP_CODE VARCHAR(10),
    COUNTY VARCHAR(50),
    LATITUDE NUMBER(10,7),
    LONGITUDE NUMBER(10,7),
    PHONE_MAIN VARCHAR(20),
    PHONE_FAX VARCHAR(20),
    EMAIL_MAIN VARCHAR(100),
    WEBSITE VARCHAR(200),
    PRINCIPAL_STAFF_ID VARCHAR(20),
    PRINCIPAL_NAME VARCHAR(100),
    BUILDING_CAPACITY NUMBER(6),
    CURRENT_ENROLLMENT NUMBER(6),
    STAFF_COUNT NUMBER(5),
    TEACHER_COUNT NUMBER(5),
    SCHOOL_YEAR VARCHAR(10),
    FIRST_DAY_OF_SCHOOL DATE,
    LAST_DAY_OF_SCHOOL DATE,
    ACCOUNTABILITY_RATING VARCHAR(20),
    GRADUATION_RATE NUMBER(5,2),
    ATTENDANCE_RATE NUMBER(5,2)
);

-- Staging table for students
CREATE OR REPLACE TABLE STAGING.STG_STUDENT (
    STUDENT_ID VARCHAR(20),
    FIRST_NAME VARCHAR(50),
    MIDDLE_NAME VARCHAR(50),
    LAST_NAME VARCHAR(50),
    PREFERRED_NAME VARCHAR(50),
    SUFFIX VARCHAR(10),
    SSN VARCHAR(11),
    STATE_ID VARCHAR(20),
    DATE_OF_BIRTH DATE,
    GENDER VARCHAR(20),
    ETHNICITY VARCHAR(50),
    RACE VARCHAR(100),
    PRIMARY_LANGUAGE VARCHAR(50),
    ELL_STATUS BOOLEAN,
    HOME_ADDRESS_LINE1 VARCHAR(100),
    HOME_ADDRESS_LINE2 VARCHAR(100),
    CITY VARCHAR(50),
    STATE VARCHAR(2),
    ZIP_CODE VARCHAR(10),
    COUNTY VARCHAR(50),
    CURRENT_SCHOOL_ID VARCHAR(20),
    CURRENT_DISTRICT_ID VARCHAR(20),
    GRADE_LEVEL VARCHAR(5),
    HOMEROOM VARCHAR(20),
    ENROLLMENT_STATUS VARCHAR(20),
    ENROLLMENT_DATE DATE,
    EXPECTED_GRADUATION_YEAR NUMBER(4),
    SPECIAL_EDUCATION BOOLEAN,
    SECTION_504 BOOLEAN,
    GIFTED_TALENTED BOOLEAN,
    FREE_REDUCED_LUNCH VARCHAR(10),
    HOMELESS_STATUS BOOLEAN
);

-- Staging table for staff
CREATE OR REPLACE TABLE STAGING.STG_STAFF (
    STAFF_ID VARCHAR(20),
    FIRST_NAME VARCHAR(50),
    MIDDLE_NAME VARCHAR(50),
    LAST_NAME VARCHAR(50),
    PREFERRED_NAME VARCHAR(50),
    EMAIL VARCHAR(100),
    PERSONAL_EMAIL VARCHAR(100),
    PHONE_WORK VARCHAR(20),
    PHONE_MOBILE VARCHAR(20),
    SSN VARCHAR(11),
    DATE_OF_BIRTH DATE,
    HOME_ADDRESS VARCHAR(200),
    CITY VARCHAR(50),
    STATE VARCHAR(2),
    ZIP_CODE VARCHAR(10),
    EMPLOYEE_TYPE VARCHAR(20),
    POSITION_TITLE VARCHAR(100),
    ROLE_CATEGORY VARCHAR(50),
    DEPARTMENT VARCHAR(50),
    PRIMARY_SCHOOL_ID VARCHAR(20),
    DISTRICT_ID VARCHAR(20),
    HIRE_DATE DATE,
    START_DATE_CURRENT_POSITION DATE,
    TERMINATION_DATE DATE,
    EMPLOYMENT_STATUS VARCHAR(20),
    HIGHEST_DEGREE VARCHAR(50),
    TEACHING_LICENSE VARCHAR(100),
    LICENSE_EXPIRATION DATE,
    YEARS_EXPERIENCE NUMBER(3),
    HIGHLY_QUALIFIED BOOLEAN,
    SALARY NUMBER(12,2),
    PAY_GRADE VARCHAR(10),
    UNION_MEMBERSHIP VARCHAR(50)
);

-- Staging table for guardians
CREATE OR REPLACE TABLE STAGING.STG_GUARDIAN (
    GUARDIAN_ID VARCHAR(20),
    FIRST_NAME VARCHAR(50),
    LAST_NAME VARCHAR(50),
    RELATIONSHIP_TYPE VARCHAR(30),
    EMAIL_PRIMARY VARCHAR(100),
    EMAIL_SECONDARY VARCHAR(100),
    PHONE_HOME VARCHAR(20),
    PHONE_MOBILE VARCHAR(20),
    PHONE_WORK VARCHAR(20),
    ADDRESS_LINE1 VARCHAR(100),
    ADDRESS_LINE2 VARCHAR(100),
    CITY VARCHAR(50),
    STATE VARCHAR(2),
    ZIP_CODE VARCHAR(10),
    EMPLOYER VARCHAR(100),
    PREFERRED_LANGUAGE VARCHAR(30),
    PORTAL_ACCOUNT_ACTIVE BOOLEAN,
    PORTAL_USERNAME VARCHAR(50),
    RECEIVES_DISTRICT_COMMUNICATIONS BOOLEAN
);

-- Staging table for student-guardian relationships
CREATE OR REPLACE TABLE STAGING.STG_STUDENT_GUARDIAN (
    RELATIONSHIP_ID VARCHAR(50),
    STUDENT_ID VARCHAR(20),
    GUARDIAN_ID VARCHAR(20),
    RELATIONSHIP_TYPE VARCHAR(30),
    IS_PRIMARY_CONTACT BOOLEAN,
    AUTHORIZED_PICKUP BOOLEAN,
    EMERGENCY_CONTACT BOOLEAN
);

-- ═══════════════════════════════════════════════════════════════════════════
-- PART 3: COPY DATA FROM STAGE TO STAGING TABLES
-- ═══════════════════════════════════════════════════════════════════════════

-- Instructions: Upload your CSV files first using:
-- PUT file:///path/to/synthetic_data/districts.csv @STAGING.DATA_STAGE/districts/
-- PUT file:///path/to/synthetic_data/schools.csv @STAGING.DATA_STAGE/schools/
-- PUT file:///path/to/synthetic_data/students.csv @STAGING.DATA_STAGE/students/
-- PUT file:///path/to/synthetic_data/staff.csv @STAGING.DATA_STAGE/staff/
-- PUT file:///path/to/synthetic_data/guardians.csv @STAGING.DATA_STAGE/guardians/
-- PUT file:///path/to/synthetic_data/student_guardians.csv @STAGING.DATA_STAGE/student_guardians/

-- Load districts
COPY INTO STAGING.STG_DISTRICT
FROM @STAGING.DATA_STAGE/districts/
FILE_FORMAT = STAGING.CSV_FORMAT
ON_ERROR = 'CONTINUE';

-- Load schools
COPY INTO STAGING.STG_SCHOOL
FROM @STAGING.DATA_STAGE/schools/
FILE_FORMAT = STAGING.CSV_FORMAT
ON_ERROR = 'CONTINUE';

-- Load students
COPY INTO STAGING.STG_STUDENT
FROM @STAGING.DATA_STAGE/students/
FILE_FORMAT = STAGING.CSV_FORMAT
ON_ERROR = 'CONTINUE';

-- Load staff
COPY INTO STAGING.STG_STAFF
FROM @STAGING.DATA_STAGE/staff/
FILE_FORMAT = STAGING.CSV_FORMAT
ON_ERROR = 'CONTINUE';

-- Load guardians
COPY INTO STAGING.STG_GUARDIAN
FROM @STAGING.DATA_STAGE/guardians/
FILE_FORMAT = STAGING.CSV_FORMAT
ON_ERROR = 'CONTINUE';

-- Load student-guardian relationships
COPY INTO STAGING.STG_STUDENT_GUARDIAN
FROM @STAGING.DATA_STAGE/student_guardians/
FILE_FORMAT = STAGING.CSV_FORMAT
ON_ERROR = 'CONTINUE';

-- ═══════════════════════════════════════════════════════════════════════════
-- PART 4: MERGE INTO RAW TABLES (SCD TYPE 2)
-- ═══════════════════════════════════════════════════════════════════════════

USE SCHEMA RAW_SIS;

-- ═══════════════════════════════════════════════════════════════════════════
-- MERGE DISTRICTS
-- ═══════════════════════════════════════════════════════════════════════════

MERGE INTO RAW_DEV.RAW_SIS.DISTRICT_RAW AS tgt
USING (
    SELECT 
        DISTRICT_ID,
        DISTRICT_NAME,
        COUNTY,
        CITY,
        COALESCE(STATE, 'MA') AS STATE,
        SUPERINTENDENT_NAME,
        PHONE_MAIN,
        WEBSITE,
        CURRENT_SCHOOL_YEAR,
        SHA2(CONCAT_WS('|',
            COALESCE(DISTRICT_ID, ''),
            COALESCE(DISTRICT_NAME, ''),
            COALESCE(COUNTY, ''),
            COALESCE(CITY, ''),
            COALESCE(STATE, ''),
            COALESCE(SUPERINTENDENT_NAME, ''),
            COALESCE(PHONE_MAIN, ''),
            COALESCE(WEBSITE, ''),
            COALESCE(CURRENT_SCHOOL_YEAR, '')
        ), 256) AS _ROW_HASH
    FROM STAGING.STG_DISTRICT
) AS src
ON tgt.DISTRICT_ID = src.DISTRICT_ID AND tgt._IS_CURRENT = TRUE
WHEN MATCHED AND tgt._ROW_HASH != src._ROW_HASH THEN
    UPDATE SET
        _IS_CURRENT = FALSE,
        _VALID_TO = CURRENT_TIMESTAMP()
WHEN NOT MATCHED THEN
    INSERT (
        DISTRICT_ID, DISTRICT_NAME, COUNTY, CITY, STATE,
        SUPERINTENDENT_NAME, PHONE_MAIN, WEBSITE, CURRENT_SCHOOL_YEAR,
        _LOADED_AT, _SOURCE_SYSTEM, _ROW_HASH, _IS_CURRENT, _VALID_FROM, _VALID_TO
    )
    VALUES (
        src.DISTRICT_ID, src.DISTRICT_NAME, src.COUNTY, src.CITY, src.STATE,
        src.SUPERINTENDENT_NAME, src.PHONE_MAIN, src.WEBSITE, src.CURRENT_SCHOOL_YEAR,
        CURRENT_TIMESTAMP(), 'FAKER_GENERATOR', src._ROW_HASH, TRUE, CURRENT_TIMESTAMP(), '9999-12-31'::TIMESTAMP_NTZ
    );

-- Insert new versions for changed records
INSERT INTO RAW_DEV.RAW_SIS.DISTRICT_RAW (
    DISTRICT_ID, DISTRICT_NAME, COUNTY, CITY, STATE,
    SUPERINTENDENT_NAME, PHONE_MAIN, WEBSITE, CURRENT_SCHOOL_YEAR,
    _LOADED_AT, _SOURCE_SYSTEM, _ROW_HASH, _IS_CURRENT, _VALID_FROM, _VALID_TO
)
SELECT 
    src.DISTRICT_ID, src.DISTRICT_NAME, src.COUNTY, src.CITY, COALESCE(src.STATE, 'MA'),
    src.SUPERINTENDENT_NAME, src.PHONE_MAIN, src.WEBSITE, src.CURRENT_SCHOOL_YEAR,
    CURRENT_TIMESTAMP(), 'FAKER_GENERATOR',
    SHA2(CONCAT_WS('|',
        COALESCE(src.DISTRICT_ID, ''),
        COALESCE(src.DISTRICT_NAME, ''),
        COALESCE(src.COUNTY, ''),
        COALESCE(src.CITY, ''),
        COALESCE(src.STATE, ''),
        COALESCE(src.SUPERINTENDENT_NAME, ''),
        COALESCE(src.PHONE_MAIN, ''),
        COALESCE(src.WEBSITE, ''),
        COALESCE(src.CURRENT_SCHOOL_YEAR, '')
    ), 256),
    TRUE, CURRENT_TIMESTAMP(), '9999-12-31'::TIMESTAMP_NTZ
FROM STAGING.STG_DISTRICT src
INNER JOIN RAW_DEV.RAW_SIS.DISTRICT_RAW tgt 
    ON src.DISTRICT_ID = tgt.DISTRICT_ID 
    AND tgt._IS_CURRENT = FALSE
    AND tgt._VALID_TO >= DATEADD('minute', -5, CURRENT_TIMESTAMP())
WHERE NOT EXISTS (
    SELECT 1 FROM RAW_DEV.RAW_SIS.DISTRICT_RAW existing
    WHERE existing.DISTRICT_ID = src.DISTRICT_ID AND existing._IS_CURRENT = TRUE
);

-- ═══════════════════════════════════════════════════════════════════════════
-- MERGE SCHOOLS
-- ═══════════════════════════════════════════════════════════════════════════

MERGE INTO RAW_DEV.RAW_SIS.SCHOOL_RAW AS tgt
USING (
    SELECT 
        SCHOOL_ID,
        SCHOOL_NAME,
        SCHOOL_NAME_SHORT,
        SCHOOL_TYPE,
        GRADE_LEVELS_SERVED,
        IS_TITLE_I,
        IS_MAGNET,
        IS_CHARTER,
        DISTRICT_ID,
        DISTRICT_NAME,
        ADDRESS,
        CITY,
        COALESCE(STATE, 'MA') AS STATE,
        ZIP_CODE,
        COUNTY,
        LATITUDE,
        LONGITUDE,
        PHONE_MAIN,
        PHONE_FAX,
        WEBSITE,
        EMAIL_MAIN,
        PRINCIPAL_STAFF_ID,
        PRINCIPAL_NAME,
        BUILDING_CAPACITY,
        CURRENT_ENROLLMENT,
        STAFF_COUNT,
        TEACHER_COUNT,
        SCHOOL_YEAR,
        FIRST_DAY_OF_SCHOOL,
        LAST_DAY_OF_SCHOOL,
        ACCOUNTABILITY_RATING,
        GRADUATION_RATE,
        ATTENDANCE_RATE,
        SHA2(CONCAT_WS('|',
            COALESCE(SCHOOL_ID, ''),
            COALESCE(SCHOOL_NAME, ''),
            COALESCE(DISTRICT_ID, ''),
            COALESCE(BUILDING_CAPACITY::VARCHAR, ''),
            COALESCE(CURRENT_ENROLLMENT::VARCHAR, ''),
            COALESCE(PRINCIPAL_NAME, '')
        ), 256) AS _ROW_HASH
    FROM STAGING.STG_SCHOOL
) AS src
ON tgt.SCHOOL_ID = src.SCHOOL_ID AND tgt._IS_CURRENT = TRUE
WHEN MATCHED AND tgt._ROW_HASH != src._ROW_HASH THEN
    UPDATE SET
        _IS_CURRENT = FALSE,
        _VALID_TO = CURRENT_TIMESTAMP()
WHEN NOT MATCHED THEN
    INSERT (
        SCHOOL_ID, SCHOOL_NAME, SCHOOL_NAME_SHORT, SCHOOL_TYPE, GRADE_LEVELS_SERVED,
        IS_TITLE_I, IS_MAGNET, IS_CHARTER, DISTRICT_ID, DISTRICT_NAME,
        ADDRESS, CITY, STATE, ZIP_CODE, COUNTY, LATITUDE, LONGITUDE,
        PHONE_MAIN, PHONE_FAX, WEBSITE, EMAIL_MAIN,
        PRINCIPAL_STAFF_ID, PRINCIPAL_NAME,
        BUILDING_CAPACITY, CURRENT_ENROLLMENT, STAFF_COUNT, TEACHER_COUNT,
        SCHOOL_YEAR, FIRST_DAY_OF_SCHOOL, LAST_DAY_OF_SCHOOL,
        ACCOUNTABILITY_RATING, GRADUATION_RATE, ATTENDANCE_RATE,
        _LOADED_AT, _SOURCE_SYSTEM, _ROW_HASH, _IS_CURRENT, _VALID_FROM, _VALID_TO
    )
    VALUES (
        src.SCHOOL_ID, src.SCHOOL_NAME, src.SCHOOL_NAME_SHORT, src.SCHOOL_TYPE, src.GRADE_LEVELS_SERVED,
        src.IS_TITLE_I, src.IS_MAGNET, src.IS_CHARTER, src.DISTRICT_ID, src.DISTRICT_NAME,
        src.ADDRESS, src.CITY, src.STATE, src.ZIP_CODE, src.COUNTY, src.LATITUDE, src.LONGITUDE,
        src.PHONE_MAIN, src.PHONE_FAX, src.WEBSITE, src.EMAIL_MAIN,
        src.PRINCIPAL_STAFF_ID, src.PRINCIPAL_NAME,
        src.BUILDING_CAPACITY, src.CURRENT_ENROLLMENT, src.STAFF_COUNT, src.TEACHER_COUNT,
        src.SCHOOL_YEAR, src.FIRST_DAY_OF_SCHOOL, src.LAST_DAY_OF_SCHOOL,
        src.ACCOUNTABILITY_RATING, src.GRADUATION_RATE, src.ATTENDANCE_RATE,
        CURRENT_TIMESTAMP(), 'FAKER_GENERATOR', src._ROW_HASH, TRUE, CURRENT_TIMESTAMP(), '9999-12-31'::TIMESTAMP_NTZ
    );

-- ═══════════════════════════════════════════════════════════════════════════
-- MERGE STUDENTS
-- ═══════════════════════════════════════════════════════════════════════════

MERGE INTO RAW_DEV.RAW_SIS.STUDENT_RAW AS tgt
USING (
    SELECT 
        STUDENT_ID,
        FIRST_NAME,
        MIDDLE_NAME,
        LAST_NAME,
        PREFERRED_NAME,
        SUFFIX,
        SSN,
        STATE_ID,
        DATE_OF_BIRTH,
        GENDER,
        ETHNICITY,
        RACE,
        PRIMARY_LANGUAGE,
        ELL_STATUS,
        HOME_ADDRESS_LINE1,
        HOME_ADDRESS_LINE2,
        CITY,
        COALESCE(STATE, 'MA') AS STATE,
        ZIP_CODE,
        COUNTY,
        CURRENT_SCHOOL_ID,
        CURRENT_DISTRICT_ID,
        GRADE_LEVEL,
        HOMEROOM,
        ENROLLMENT_STATUS,
        ENROLLMENT_DATE,
        EXPECTED_GRADUATION_YEAR,
        SPECIAL_EDUCATION,
        SECTION_504,
        GIFTED_TALENTED,
        FREE_REDUCED_LUNCH,
        HOMELESS_STATUS,
        SHA2(CONCAT_WS('|',
            COALESCE(STUDENT_ID, ''),
            COALESCE(FIRST_NAME, ''),
            COALESCE(LAST_NAME, ''),
            COALESCE(CURRENT_SCHOOL_ID, ''),
            COALESCE(GRADE_LEVEL, ''),
            COALESCE(ENROLLMENT_STATUS, '')
        ), 256) AS _ROW_HASH
    FROM STAGING.STG_STUDENT
) AS src
ON tgt.STUDENT_ID = src.STUDENT_ID AND tgt._IS_CURRENT = TRUE
WHEN MATCHED AND tgt._ROW_HASH != src._ROW_HASH THEN
    UPDATE SET
        _IS_CURRENT = FALSE,
        _VALID_TO = CURRENT_TIMESTAMP()
WHEN NOT MATCHED THEN
    INSERT (
        STUDENT_ID, FIRST_NAME, MIDDLE_NAME, LAST_NAME, PREFERRED_NAME, SUFFIX,
        SSN, STATE_ID, DATE_OF_BIRTH, GENDER, ETHNICITY, RACE, PRIMARY_LANGUAGE, ELL_STATUS,
        HOME_ADDRESS_LINE1, HOME_ADDRESS_LINE2, CITY, STATE, ZIP_CODE, COUNTY,
        CURRENT_SCHOOL_ID, CURRENT_DISTRICT_ID, GRADE_LEVEL, HOMEROOM,
        ENROLLMENT_STATUS, ENROLLMENT_DATE, EXPECTED_GRADUATION_YEAR,
        SPECIAL_EDUCATION, SECTION_504, GIFTED_TALENTED, FREE_REDUCED_LUNCH, HOMELESS_STATUS,
        _LOADED_AT, _SOURCE_SYSTEM, _ROW_HASH, _IS_CURRENT, _VALID_FROM, _VALID_TO
    )
    VALUES (
        src.STUDENT_ID, src.FIRST_NAME, src.MIDDLE_NAME, src.LAST_NAME, src.PREFERRED_NAME, src.SUFFIX,
        src.SSN, src.STATE_ID, src.DATE_OF_BIRTH, src.GENDER, src.ETHNICITY, src.RACE, src.PRIMARY_LANGUAGE, src.ELL_STATUS,
        src.HOME_ADDRESS_LINE1, src.HOME_ADDRESS_LINE2, src.CITY, src.STATE, src.ZIP_CODE, src.COUNTY,
        src.CURRENT_SCHOOL_ID, src.CURRENT_DISTRICT_ID, src.GRADE_LEVEL, src.HOMEROOM,
        src.ENROLLMENT_STATUS, src.ENROLLMENT_DATE, src.EXPECTED_GRADUATION_YEAR,
        src.SPECIAL_EDUCATION, src.SECTION_504, src.GIFTED_TALENTED, src.FREE_REDUCED_LUNCH, src.HOMELESS_STATUS,
        CURRENT_TIMESTAMP(), 'FAKER_GENERATOR', src._ROW_HASH, TRUE, CURRENT_TIMESTAMP(), '9999-12-31'::TIMESTAMP_NTZ
    );

-- ═══════════════════════════════════════════════════════════════════════════
-- MERGE GUARDIANS
-- ═══════════════════════════════════════════════════════════════════════════

MERGE INTO RAW_DEV.RAW_SIS.GUARDIAN_RAW AS tgt
USING (
    SELECT 
        GUARDIAN_ID,
        FIRST_NAME,
        LAST_NAME,
        RELATIONSHIP_TYPE,
        EMAIL_PRIMARY,
        EMAIL_SECONDARY,
        PHONE_HOME,
        PHONE_MOBILE,
        PHONE_WORK,
        ADDRESS_LINE1,
        ADDRESS_LINE2,
        CITY,
        COALESCE(STATE, 'MA') AS STATE,
        ZIP_CODE,
        EMPLOYER,
        PREFERRED_LANGUAGE,
        PORTAL_ACCOUNT_ACTIVE,
        PORTAL_USERNAME,
        RECEIVES_DISTRICT_COMMUNICATIONS,
        SHA2(CONCAT_WS('|',
            COALESCE(GUARDIAN_ID, ''),
            COALESCE(FIRST_NAME, ''),
            COALESCE(LAST_NAME, ''),
            COALESCE(EMAIL_PRIMARY, ''),
            COALESCE(PHONE_MOBILE, '')
        ), 256) AS _ROW_HASH
    FROM STAGING.STG_GUARDIAN
) AS src
ON tgt.GUARDIAN_ID = src.GUARDIAN_ID AND tgt._IS_CURRENT = TRUE
WHEN MATCHED AND tgt._ROW_HASH != src._ROW_HASH THEN
    UPDATE SET
        _IS_CURRENT = FALSE,
        _VALID_TO = CURRENT_TIMESTAMP()
WHEN NOT MATCHED THEN
    INSERT (
        GUARDIAN_ID, FIRST_NAME, LAST_NAME, RELATIONSHIP_TYPE,
        EMAIL_PRIMARY, EMAIL_SECONDARY, PHONE_HOME, PHONE_MOBILE, PHONE_WORK,
        ADDRESS_LINE1, ADDRESS_LINE2, CITY, STATE, ZIP_CODE,
        EMPLOYER, PREFERRED_LANGUAGE, PORTAL_ACCOUNT_ACTIVE, PORTAL_USERNAME, RECEIVES_DISTRICT_COMMUNICATIONS,
        _LOADED_AT, _SOURCE_SYSTEM, _ROW_HASH, _IS_CURRENT, _VALID_FROM, _VALID_TO
    )
    VALUES (
        src.GUARDIAN_ID, src.FIRST_NAME, src.LAST_NAME, src.RELATIONSHIP_TYPE,
        src.EMAIL_PRIMARY, src.EMAIL_SECONDARY, src.PHONE_HOME, src.PHONE_MOBILE, src.PHONE_WORK,
        src.ADDRESS_LINE1, src.ADDRESS_LINE2, src.CITY, src.STATE, src.ZIP_CODE,
        src.EMPLOYER, src.PREFERRED_LANGUAGE, src.PORTAL_ACCOUNT_ACTIVE, src.PORTAL_USERNAME, src.RECEIVES_DISTRICT_COMMUNICATIONS,
        CURRENT_TIMESTAMP(), 'FAKER_GENERATOR', src._ROW_HASH, TRUE, CURRENT_TIMESTAMP(), '9999-12-31'::TIMESTAMP_NTZ
    );

-- ═══════════════════════════════════════════════════════════════════════════
-- MERGE STUDENT-GUARDIAN RELATIONSHIPS
-- ═══════════════════════════════════════════════════════════════════════════

MERGE INTO RAW_DEV.RAW_SIS.STUDENT_GUARDIAN_RAW AS tgt
USING (
    SELECT 
        RELATIONSHIP_ID,
        STUDENT_ID,
        GUARDIAN_ID,
        RELATIONSHIP_TYPE,
        IS_PRIMARY_CONTACT,
        AUTHORIZED_PICKUP,
        EMERGENCY_CONTACT
    FROM STAGING.STG_STUDENT_GUARDIAN
) AS src
ON tgt.RELATIONSHIP_ID = src.RELATIONSHIP_ID AND tgt._IS_CURRENT = TRUE
WHEN NOT MATCHED THEN
    INSERT (
        RELATIONSHIP_ID, STUDENT_ID, GUARDIAN_ID, RELATIONSHIP_TYPE,
        IS_PRIMARY_CONTACT, AUTHORIZED_PICKUP, EMERGENCY_CONTACT,
        _LOADED_AT, _SOURCE_SYSTEM, _IS_CURRENT
    )
    VALUES (
        src.RELATIONSHIP_ID, src.STUDENT_ID, src.GUARDIAN_ID, src.RELATIONSHIP_TYPE,
        src.IS_PRIMARY_CONTACT, src.AUTHORIZED_PICKUP, src.EMERGENCY_CONTACT,
        CURRENT_TIMESTAMP(), 'FAKER_GENERATOR', TRUE
    );

-- ═══════════════════════════════════════════════════════════════════════════
-- MERGE STAFF (HR Schema)
-- ═══════════════════════════════════════════════════════════════════════════

USE SCHEMA RAW_HR;

MERGE INTO RAW_DEV.RAW_HR.STAFF_RAW AS tgt
USING (
    SELECT 
        STAFF_ID,
        FIRST_NAME,
        MIDDLE_NAME,
        LAST_NAME,
        PREFERRED_NAME,
        EMAIL,
        PERSONAL_EMAIL,
        PHONE_WORK,
        PHONE_MOBILE,
        SSN,
        DATE_OF_BIRTH,
        HOME_ADDRESS,
        CITY,
        COALESCE(STATE, 'MA') AS STATE,
        ZIP_CODE,
        EMPLOYEE_TYPE,
        POSITION_TITLE,
        ROLE_CATEGORY,
        DEPARTMENT,
        PRIMARY_SCHOOL_ID,
        DISTRICT_ID,
        HIRE_DATE,
        START_DATE_CURRENT_POSITION,
        TERMINATION_DATE,
        EMPLOYMENT_STATUS,
        HIGHEST_DEGREE,
        TEACHING_LICENSE,
        LICENSE_EXPIRATION,
        YEARS_EXPERIENCE,
        HIGHLY_QUALIFIED,
        SALARY,
        PAY_GRADE,
        UNION_MEMBERSHIP,
        SHA2(CONCAT_WS('|',
            COALESCE(STAFF_ID, ''),
            COALESCE(FIRST_NAME, ''),
            COALESCE(LAST_NAME, ''),
            COALESCE(PRIMARY_SCHOOL_ID, ''),
            COALESCE(POSITION_TITLE, ''),
            COALESCE(EMPLOYMENT_STATUS, '')
        ), 256) AS _ROW_HASH
    FROM STAGING.STG_STAFF
) AS src
ON tgt.STAFF_ID = src.STAFF_ID AND tgt._IS_CURRENT = TRUE
WHEN MATCHED AND tgt._ROW_HASH != src._ROW_HASH THEN
    UPDATE SET
        _IS_CURRENT = FALSE,
        _VALID_TO = CURRENT_TIMESTAMP()
WHEN NOT MATCHED THEN
    INSERT (
        STAFF_ID, FIRST_NAME, MIDDLE_NAME, LAST_NAME, PREFERRED_NAME,
        EMAIL, PERSONAL_EMAIL, PHONE_WORK, PHONE_MOBILE,
        SSN, DATE_OF_BIRTH, HOME_ADDRESS, CITY, STATE, ZIP_CODE,
        EMPLOYEE_TYPE, POSITION_TITLE, ROLE_CATEGORY, DEPARTMENT,
        PRIMARY_SCHOOL_ID, DISTRICT_ID,
        HIRE_DATE, START_DATE_CURRENT_POSITION, TERMINATION_DATE, EMPLOYMENT_STATUS,
        HIGHEST_DEGREE, TEACHING_LICENSE, LICENSE_EXPIRATION, YEARS_EXPERIENCE, HIGHLY_QUALIFIED,
        SALARY, PAY_GRADE, UNION_MEMBERSHIP,
        _LOADED_AT, _SOURCE_SYSTEM, _ROW_HASH, _IS_CURRENT, _VALID_FROM, _VALID_TO
    )
    VALUES (
        src.STAFF_ID, src.FIRST_NAME, src.MIDDLE_NAME, src.LAST_NAME, src.PREFERRED_NAME,
        src.EMAIL, src.PERSONAL_EMAIL, src.PHONE_WORK, src.PHONE_MOBILE,
        src.SSN, src.DATE_OF_BIRTH, src.HOME_ADDRESS, src.CITY, src.STATE, src.ZIP_CODE,
        src.EMPLOYEE_TYPE, src.POSITION_TITLE, src.ROLE_CATEGORY, src.DEPARTMENT,
        src.PRIMARY_SCHOOL_ID, src.DISTRICT_ID,
        src.HIRE_DATE, src.START_DATE_CURRENT_POSITION, src.TERMINATION_DATE, src.EMPLOYMENT_STATUS,
        src.HIGHEST_DEGREE, src.TEACHING_LICENSE, src.LICENSE_EXPIRATION, src.YEARS_EXPERIENCE, src.HIGHLY_QUALIFIED,
        src.SALARY, src.PAY_GRADE, src.UNION_MEMBERSHIP,
        CURRENT_TIMESTAMP(), 'FAKER_GENERATOR', src._ROW_HASH, TRUE, CURRENT_TIMESTAMP(), '9999-12-31'::TIMESTAMP_NTZ
    );

-- ═══════════════════════════════════════════════════════════════════════════
