SELECT 'Data Load Complete' AS STATUS;

SELECT 'Districts' AS TABLE_NAME, COUNT(*) AS ROW_COUNT FROM RAW_DEV.RAW_SIS.DISTRICT_RAW WHERE _IS_CURRENT = TRUE
UNION ALL
SELECT 'Schools' AS TABLE_NAME, COUNT(*) AS ROW_COUNT FROM RAW_DEV.RAW_SIS.SCHOOL_RAW WHERE _IS_CURRENT = TRUE
UNION ALL
SELECT 'Students' AS TABLE_NAME, COUNT(*) AS ROW_COUNT FROM RAW_DEV.RAW_SIS.STUDENT_RAW WHERE _IS_CURRENT = TRUE
UNION ALL
SELECT 'Guardians' AS TABLE_NAME, COUNT(*) AS ROW_COUNT FROM RAW_DEV.RAW_SIS.GUARDIAN_RAW WHERE _IS_CURRENT = TRUE
UNION ALL
SELECT 'Student-Guardian' AS TABLE_NAME, COUNT(*) AS ROW_COUNT FROM RAW_DEV.RAW_SIS.STUDENT_GUARDIAN_RAW WHERE _IS_CURRENT = TRUE
UNION ALL
SELECT 'Staff' AS TABLE_NAME, COUNT(*) AS ROW_COUNT FROM RAW_DEV.RAW_HR.STAFF_RAW WHERE _IS_CURRENT = TRUE;

